import math

def violations(f, grid, thetas=(0.25, 0.5, 0.75), tol=1e-9):
    # count the triples (x, y, theta) where the graph rises above the chord
    count = 0
    for x in grid:
        for y in grid:
            for t in thetas:
                chord = t * f(x) + (1 - t) * f(y)
                if f(t * x + (1 - t) * y) > chord + tol:
                    count += 1
    return count

grid = [k / 4 for k in range(25)]     # 0, 0.25, ..., 6
tests = len(grid) ** 2 * 3
print("x^2:", violations(lambda x: x * x, grid), "of", tests)
print("sin on [0, 6]:", violations(math.sin, grid), "of", tests)

