def is_convex_samples(xs, ys):
    slopes = [(ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]) for i in range(len(xs) - 1)]
    return all(s1 <= s2 for s1, s2 in zip(slopes, slopes[1:]))
